  /** Represents the current application to register shutdown hooks. */
  @J2ktIncompatible
  @GwtIncompatible // TODO
  @VisibleForTesting
  static class Application {

    private static final long DEFAULT_SHUTDOWN_TIMEOUT_SECS = 120;

    final ExecutorService getExitingExecutorService(
        ThreadPoolExecutor executor, long terminationTimeout, TimeUnit timeUnit) {
      useDaemonThreadFactory(executor);
      ExecutorService service = unconfigurableExecutorService(executor);
      addDelayedShutdownHook(executor, terminationTimeout, timeUnit);
      return service;
    }

    final ExecutorService getExitingExecutorService(ThreadPoolExecutor executor) {
      return getExitingExecutorService(executor, DEFAULT_SHUTDOWN_TIMEOUT_SECS, SECONDS);
    }

    final ScheduledExecutorService getExitingScheduledExecutorService(
        ScheduledThreadPoolExecutor executor, long terminationTimeout, TimeUnit timeUnit) {
      useDaemonThreadFactory(executor);
      ScheduledExecutorService service = unconfigurableScheduledExecutorService(executor);
      addDelayedShutdownHook(executor, terminationTimeout, timeUnit);
      return service;
    }

    final ScheduledExecutorService getExitingScheduledExecutorService(
        ScheduledThreadPoolExecutor executor) {
      return getExitingScheduledExecutorService(executor, DEFAULT_SHUTDOWN_TIMEOUT_SECS, SECONDS);
    }

    final void addDelayedShutdownHook(
        ExecutorService service, long terminationTimeout, TimeUnit timeUnit) {
      checkNotNull(service, "service");
      checkNotNull(timeUnit, "timeUnit");
      addShutdownHook(
          newThread(
              "DelayedShutdownHook-for-" + service,
              () -> {
                service.shutdown();
                try {
                  // We'd like to log progress and failures that may arise in the
                  // following code, but unfortunately the behavior of logging
                  // is undefined in shutdown hooks.
                  // This is because the logging code installs a shutdown hook of its
                  // own. See Cleaner class inside {@link LogManager}.
                  service.awaitTermination(terminationTimeout, timeUnit);
                } catch (InterruptedException ignored) {
                  // We're shutting down anyway, so just ignore.
                }
              }));
    }

    @VisibleForTesting
    void addShutdownHook(Thread hook) {
      Runtime.getRuntime().addShutdownHook(hook);
    }

    Application() {}
  }

  @J2ktIncompatible
